import{_ as o,o as t,c as i,a4 as a}from"./chunks/framework.CmuCl-jw.js";const u=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"local/troubleshooting.md","filePath":"local/troubleshooting.md"}'),s={name:"local/troubleshooting.md"};function n(r,e,d,c,l,h){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h1><h2 id="windows-docker-desktop-data-is-not-writable-troubleshooting-blurb-copy-paste" tabindex="-1">Windows + Docker Desktop: “/data is not writable” troubleshooting blurb (copy/paste) <a class="header-anchor" href="#windows-docker-desktop-data-is-not-writable-troubleshooting-blurb-copy-paste" aria-label="Permalink to “Windows + Docker Desktop: “/data is not writable” troubleshooting blurb (copy/paste)”">​</a></h2><ul><li>Check Docker Desktop is running (the whale icon should be active). If it isn’t, docker compose commands may hang or fail.</li><li>Verify the host folder exists and is accessible: create the directory referenced by SHARED_DATA_PATH in File Explorer (and ensure you can create a file in it).</li><li>Avoid network / cloud-synced paths at first (common culprits: UNC paths like \\server\\share, mapped drives, OneDrive/SharePoint-synced folders). Prefer something simple like C:\\Users&lt;name&gt;\\ArcsecondData.</li><li>If you use another drive (D:\\ / external drive): enable sharing in Docker Desktop. Go to Docker Desktop → Settings → Resources → File sharing (wording may vary) and add the drive/folder, then Apply &amp; Restart.</li><li>Confirm the mount from inside a container (quick sanity check): Run a one-off container that writes a test file to /data and confirm the file appears on the host. If it can’t write, it’s almost always a sharing/permissions/path issue.</li></ul><h2 id="linux-permission-denied-while-trying-to-connect-to-the-docker-api" tabindex="-1">Linux: &quot;permission denied while trying to connect to the docker API&quot; <a class="header-anchor" href="#linux-permission-denied-while-trying-to-connect-to-the-docker-api" aria-label="Permalink to “Linux: &quot;permission denied while trying to connect to the docker API&quot;”">​</a></h2><p>The full line is <code>permission denied while trying to connect to the docker API at unix:///var/run/docker.sock</code>, and it shows up right after <code>docker compose up -d</code> on a Linux host running Docker Engine (not Docker Desktop). The daemon only answers root and members of the <code>docker</code> group, and a fresh install does not put your user there. <code>docker login</code> succeeds regardless, because it only writes a config file, which is why the failure looks sudden.</p><p>Add your user to the group once, then log out and back in (or <code>newgrp docker</code> in the current shell), and check with <code>docker ps</code> before running <code>docker compose up -d</code> again:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usermod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -aG</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $USER</span></span></code></pre></div><h2 id="the-xyz-variable-is-not-set-defaulting-to-a-blank-string" tabindex="-1">&quot;The &#39;xyz&#39; variable is not set. Defaulting to a blank string.&quot; <a class="header-anchor" href="#the-xyz-variable-is-not-set-defaulting-to-a-blank-string" aria-label="Permalink to “&quot;The &#39;xyz&#39; variable is not set. Defaulting to a blank string.&quot;”">​</a></h2><p>Repeated <code>WARN[0000] The &quot;...&quot; variable is not set</code> lines on <code>docker compose up</code>, with names that look like random fragments, come from a <code>$</code> inside one of the secret keys that <code>arcsecond setup</code> wrote to <code>.env</code>. Compose interpolates <code>$name</code> in that file, so the <code>$</code> and the characters after it are dropped. Versions of the CLI up to 3.17.1 could generate such keys; later versions do not.</p><p>The containers all see the same shortened value, so an installation that runs with these warnings is fine as it is. On a <strong>brand new</strong> installation that has not started yet, the cleaner move is to open <code>.env</code> and remove every <code>$</code> from <code>SECRET_KEY</code>, <code>AUTH_JWT_SIGNING_KEY</code> and <code>AGENT_JWT_SIGNING_KEY</code> (or delete <code>.env</code> and rerun <code>arcsecond setup</code> with an up-to-date CLI). Do not touch these three keys on an installation that already has users: they sign every session token, and changing them logs everyone out.</p>',10)])])}const k=o(s,[["render",n]]);export{u as __pageData,k as default};
